@app.middleware("http")
async def tunnel_write_guard(request: Request, call_next):
    if request.method in ("POST", "PUT", "PATCH", "DELETE"):
        via_tunnel = bool(request.headers.get("cf-ray") or request.headers.get("cf-connecting-ip"))
        if via_tunnel:
            tok = _write_token()
            supplied = request.headers.get("x-qi-token") or request.query_params.get("qi_token", "")
            if not tok or supplied != tok:
                return JSONResponse({"status": "error", "error": "write access via tunnel requires X-QI-Token"},
                                    status_code=403)
    return await call_next(request)

class QI:
    @staticmethod
    def port(project_id: str, service: str = "api") -> int | None:
        proj = _PROJECTS.get(project_id, {})
        ports = proj.get("ports", {})
        entry = ports.get(service, {})
        return entry.get("current")

    @staticmethod
    def cors_origins() -> list[str]:
        origins = []
        for proj in _PROJECTS.values():
            for service_key, service_val in proj.get("ports", {}).items():
                p = service_val.get("current")
                if p:
                    origins.append(f"http://localhost:{p}")
                    origins.append(f"http://127.0.0.1:{p}")
        return list(set(origins))

